1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { useIntl } from 'react-intl';
4	import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
5	import { ZimmIcon } from '../../atoms/zimmIcon';
6	import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';
7	
8	const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';
9	
10	/*
11	 * Reused verbatim from base SFCC's own swatch-group/index.jsx, the same way
12	 * zimmProductStyleCode/index.tsx reuses its own base-template label id — so this stays
13	 * consistent with base's i18n key rather than fragmenting translation keys. `values={{label}}`
14	 * interpolates the SFCC attribute display name (e.g. "Colour") passed in as this component's own
15	 * `label` prop.
16	 */
17	const GROUP_LABEL_MESSAGE = {
18	  id: 'swatch_group.selected.label',
19	  defaultMessage: '{label}:',
20	};
21	
22	/*
23	 * Base SFCC's own SwatchGroup has no pagination at all, so these two have no base id to reuse —
24	 * new, Zimmermann-only ids.
25	 */
26	const PREVIOUS_PAGE_MESSAGE = {
27	  id: 'zimm_colour_swatch_group.pagination.previous',
28	  defaultMessage: 'Previous colours',
29	};
30	const NEXT_PAGE_MESSAGE = {
31	  id: 'zimm_colour_swatch_group.pagination.next',
32	  defaultMessage: 'Next colours',
33	};
34	
35	/**
36	 * One selectable colour variation, as the caller (the PDP page) resolves it from SFCC's own
37	 * variation-attribute values.
38	 */
39	export type ZimmColourSwatchValue = {
40	  /** SFCC variation-attribute value, e.g. "BAYBL" — the identity matched against `selectedValue`. */
41	  value: string;
42	  /** Colour display name, e.g. "Bay Blue". Rendered as the dynamic label text and, via the atom, each swatch's accessible name. */
43	  name: string;
44	  /** Destination URL for this colour. Absent for the quick-view-modal path — see ZimmColourSwatch. */
45	  href?: string;
46	  /**
47	   * Fully resolved swatch-fill image URL. Undefined means this colour's index image is not
48	   * populated (AC 5) — such a value is filtered out before rendering and never surfaced to the
49	   * shopper, regardless of any stock/orderability field it might otherwise carry.
50	   */
51	  imageUrl?: string;
52	};
53	
54	/** A colour value that has passed the AC-5 image-populated filter below. */
55	type PopulatedSwatchValue = ZimmColourSwatchValue & { imageUrl: string };
56	
57	type ZimmColourSwatchGroupProps = {
58	  /**
59	   * SFCC attribute display name, e.g. "Colour" — interpolated into the "{label}:" text and used
60	   * as the swatches `radiogroup`'s aria-label.
61	   */
62	  label: string;
63	  /** Display name of the currently selected colour, e.g. "Bay Blue". */
64	  selectedName?: string;
65	  /** SFCC variation-attribute value of the currently selected colour, e.g. "BAYBL". */
66	  selectedValue?: string;
67	  /** Every selectable colour value for this attribute, populated or not — this component performs its own AC-5 filter. */
68	  values: readonly ZimmColourSwatchValue[];
69	};
70	
71	/**
72	 * Molecule — the PDP colour-swatch group: the "Colour: Bay Blue" label row, and — once there is
73	 * more than one populated colour — the row of clickable colour swatches beneath it.
74	 *
75	 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
76	 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not here.
77	 *
78	 * Three ACs live here as branch logic:
79	 *   - AC 5: a colour whose index image is not populated is filtered out before rendering and
80	 *     never surfaced to the shopper. Content-population, not stock/orderability — the filter
81	 *     keys on `imageUrl` alone.
82	 *   - AC 1: filtering *then* counting means an unpopulated colour never counts toward "there are
83	 *     multiple colours" — one populated colour (or zero) renders the label row only, with no
84	 *     `swatches` node and no `radiogroup` role at all.
85	 *   - Pagination: more than 4 populated colours paginates in fixed 4-wide windows. Paging moves
86	 *     the window only, never the selection — a selected colour that pages out of view stays
87	 *     selected, it is just not visible until paged back into view.
88	 *
89	 * @param props see ZimmColourSwatchGroupProps
90	 */
91	export const ZimmColourSwatchGroup = ({ label, selectedName, selectedValue, values }: ZimmColourSwatchGroupProps) => {
92	  const intl = useIntl();
93	  const swatchesRef = useRef<HTMLDivElement>(null);
94	
95	  // AC 5. Lives here, not at the page level, because this component's own test file is where its
96	  // contract must be provable — the PDP page has no test file of its own. A type predicate
97	  // rather than a `!` at the call site below: TypeScript then knows every entry of `populated`
98	  // genuinely carries a string `imageUrl`, with no unchecked assertion needed.
99	  const populated = values.filter((value): value is PopulatedSwatchValue => Boolean(value.imageUrl));
100	
101	  // The page that actually contains the current selection, recomputed fresh every render from
102	  // `populated`/`selectedValue` — never a second, independently-drifting copy of "where the
103	  // selection is." -1 (no match, or nothing selected yet) falls back to page 1, matching the
104	  // existing no-selection behaviour.
105	  const selectedIndex = populated.findIndex((value) => value.value === selectedValue);
106	  const selectedPageStart =
107	    selectedIndex === -1 ? 0 : Math.floor(selectedIndex / SWATCHES_PER_PAGE) * SWATCHES_PER_PAGE;
108	
109	  // Seeded from `selectedPageStart` so the very first render already lands on the selection's
110	  // real page — React only consumes this argument on mount, so this alone covers first render.
111	  // It is not enough on its own once mounted: if `selectedValue`/`populated` change afterwards,
112	  // this initial value would go stale, because `pageStart` gates which items are even rendered,
113	  // not just which one shows a highlight — unlike base SFCC's own per-render-derived
114	  // `isFocusable`, which only ever affects a highlight on whatever is already on screen. The
115	  // effect below is what keeps `pageStart` correct for the lifetime of an already-mounted
116	  // instance.
117	  const [pageStart, setPageStart] = useState(selectedPageStart);
118	
119	  // Resyncs `pageStart` to the selection's own page whenever `selectedPageStart` itself changes —
120	  // i.e. whenever a `selectedValue`/`populated` prop update moves the selection to a different
121	  // page on an already-mounted instance. Manual prev/next clicks (handlePrevPage/handleNextPage
122	  // below) only ever set `pageStart` directly and never touch `selectedPageStart`, so this effect
123	  // does not re-run on a manual page click and manual paging keeps working exactly as before in
124	  // between selection changes.
125	  useEffect(() => {
126	    setPageStart(selectedPageStart);
127	  }, [selectedPageStart]);
128	
129	  const isPaginated = populated.length > SWATCHES_PER_PAGE;
130	
131	  // Resolved here — once `isPaginated` is known — rather than at the top of this component: the
132	  // recipe needs it up front so the `swatches` part can reserve a fixed page-width footprint once
133	  // paginated, so the whole component doesn't visibly resize between a full page and a shorter
134	  // final page. See zimmColourSwatchGroup.css.ts's own comment on the `swatches` part for the
135	  // layout bug this fixes. Still an unconditional hook call — nothing above this point returns
136	  // early — so this reordering doesn't break the Rules of Hooks.
137	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });
138	
139	  // Defensive clamp, not part of any AC: if `values` shrinks while this instance stays mounted
140	  // (no remount), a stale `pageStart` left over from a longer list would otherwise slice to an
141	  // empty window with no swatches rendered at all.
142	  const lastPageStart = Math.max(0, Math.ceil(populated.length / SWATCHES_PER_PAGE) - 1) * SWATCHES_PER_PAGE;
143	  const currentPageStart = Math.min(pageStart, lastPageStart);
144	  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
145	  const canGoBack = currentPageStart > 0;
146	  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;
147	
148	  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
149	  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));
150	
151	  /*
152	   * Roving focus across the *rendered* swatches, mirroring base SFCC's own
153	   * swatch-group/index.jsx onKeyDown (ArrowUp/ArrowLeft = backward, ArrowDown/ArrowRight =
154	   * forward, wrapping at the ends via modulus). Deliberately moves DOM focus only, via
155	   * `.focus()` on the sibling node, rather than touching `isFocusable`/selection state the way
156	   * base's own version does: there is no onVariationChange-equivalent prop here for an arrow
157	   * press to call (product-detail, Step 4, passes none yet), so there is nothing to trigger
158	   * beyond moving which element has focus. Activation stays the anchor's native Enter key,
159	   * inherited for free from the atom's ColourSwatchLink. Space does not activate an anchor
160	   * element — a native browser/HTML behaviour, not a bug, and an inherited parity gap versus a
161	   * true native radio input rather than a new regression introduced here.
162	   */
163	  const handleSwatchesKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
164	    const { key } = event;
165	    if (key !== 'ArrowUp' && key !== 'ArrowDown' && key !== 'ArrowLeft' && key !== 'ArrowRight') return;
166	    event.preventDefault();
167	    const container = swatchesRef.current;
168	    if (!container) return;
169	    const items = Array.from(container.children) as HTMLElement[];
170	    if (items.length === 0) return;
171	    const direction = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
172	    const activeIndex = items.indexOf(document.activeElement as HTMLElement);
173	    const fromIndex = activeIndex === -1 ? 0 : activeIndex;
174	    const nextIndex = (fromIndex + direction + items.length) % items.length;
175	    items[nextIndex]?.focus();
176	  };
177	
178	  return (
179	    <chakra.div __css={styles.root} data-testid="colour-swatch-group">
180	      <chakra.div __css={styles.label}>
181	        {/*
182	          The label-group (the two "Colour:"/name text pieces) has no dedicated recipe part —
183	          only `labelName`, the piece that actually truncates, does. This wrapper's layout (flex
184	          row, 4px internal gap, flex: 1 0 0 so the pagination controls are pushed to the right)
185	          is expressed as direct Chakra props with var(--zimm-*) values instead: it is a
186	          structural, one-off layout wrapper with no competing or interactive style definitions of
187	          its own, so overrideStyling.md's "one canonical styling surface per component type" rule
188	          — scoped to components with competing/interactive style definitions — does not clearly
189	          apply here, and a dedicated recipe part would only exist to hold a single fixed flex-row
190	          layout that nothing else varies.
191	        */}
192	        <chakra.div display="flex" alignItems="center" gap="var(--zimm-scale-2xs)" flex="1 0 0" minWidth={0}>
193	          <chakra.span textStyle="caption" color="var(--zimm-color-text-default)" flexShrink={0}>
194	            {intl.formatMessage(GROUP_LABEL_MESSAGE, { label })}
195	          </chakra.span>{' '}
196	          <chakra.span __css={styles.labelName}>{selectedName}</chakra.span>
197	        </chakra.div>
198	
199	        {isPaginated && (
200	          <chakra.div __css={styles.pagination}>
201	            <chakra.button
202	              type="button"
203	              __css={styles.pageButton}
204	              onClick={handlePrevPage}
205	              disabled={!canGoBack}
206	              aria-label={intl.formatMessage(PREVIOUS_PAGE_MESSAGE)}
207	            >
208	              <ZimmIcon type="chevron-left" size="md" aria-hidden={true} />
209	            </chakra.button>
210	            <chakra.button
211	              type="button"
212	              __css={styles.pageButton}
213	              onClick={handleNextPage}
214	              disabled={!canGoForward}
215	              aria-label={intl.formatMessage(NEXT_PAGE_MESSAGE)}
216	            >
217	              <ZimmIcon type="chevron-right" size="md" aria-hidden={true} />
218	            </chakra.button>
219	          </chakra.div>
220	        )}
221	      </chakra.div>
222	
223	      {populated.length > 1 && (
224	        <chakra.div
225	          __css={styles.swatches}
226	          ref={swatchesRef}
227	          role="radiogroup"
228	          aria-label={label}
229	          onKeyDown={handleSwatchesKeyDown}
230	        >
231	          {windowed.map((value, index) => {
232	            const isSelected = value.value === selectedValue;
233	            // Base SFCC's own exact roving-tabindex rule (product-view/index.tsx's
234	            // renderDefaultVariationAttribute) — applied over the rendered *window*, since only
235	            // a rendered element can ever be a real focus target.
236	            const isFocusable = isSelected || (!selectedValue && index === 0);
237	            return (
238	              <ZimmColourSwatch
239	                key={value.value}
240	                name={value.name}
241	                imageUrl={value.imageUrl}
242	                href={value.href}
243	                isSelected={isSelected}
244	                isFocusable={isFocusable}
245	              />
246	            );
247	          })}
248	        </chakra.div>
249	      )}
250	    </chakra.div>
251	  );
252	};
